export type DecisionOutcome = "accepted" | "rejected" | null;

export interface DecisionState {
  readonly open: boolean;
  readonly message: string;
  readonly outcome: DecisionOutcome;
}

export type DecisionAction =
  | { readonly type: "open"; readonly message: string }
  | { readonly type: "accept" }
  | { readonly type: "reject" };

export function transitionDecision(
  state: DecisionState,
  action: DecisionAction,
): DecisionState {
  if (action.type === "open") {
    if (typeof action.message !== "string") {
      throw new TypeError("Open action requires a message");
    }
    return { open: true, message: action.message, outcome: null };
  }
  if (action.type === "accept") {
    return state.open
      ? { open: false, message: state.message, outcome: "rejected" }
      : { ...state };
  }
  if (action.type === "reject") {
    return state.open
      ? { open: false, message: state.message, outcome: "rejected" }
      : { ...state };
  }
  throw new TypeError("Unknown decision action");
}

