import { transitionDecision, DecisionState, DecisionAction } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const closed: DecisionState = Object.freeze({ open: false, message: 'old', outcome: 'rejected' });
const openAction: DecisionAction = Object.freeze({ type: 'open', message: '' });
const opened = transitionDecision(closed, openAction);
deepEqual(opened, { open: true, message: '', outcome: null }, 'open stores empty message and clears outcome');
deepEqual(closed, { open: false, message: 'old', outcome: 'rejected' }, 'does not mutate state');
deepEqual(openAction, { type: 'open', message: '' }, 'does not mutate action');
assert(opened !== closed, 'open returns a fresh object');

const withMessage = transitionDecision(opened, { type: 'open', message: '  verbatim  ' });
deepEqual(withMessage, { open: true, message: '  verbatim  ', outcome: null }, 'preserves message verbatim');

const accepted = transitionDecision(withMessage, { type: 'accept' });
deepEqual(accepted, { open: false, message: '  verbatim  ', outcome: 'accepted' }, 'accepts an open prompt');
const rejected = transitionDecision(withMessage, { type: 'reject' });
deepEqual(rejected, { open: false, message: '  verbatim  ', outcome: 'rejected' }, 'rejects an open prompt');

const acceptNoOp = transitionDecision(closed, { type: 'accept' });
const rejectNoOp = transitionDecision(closed, { type: 'reject' });
deepEqual(acceptNoOp, closed, 'accept is value no-op when closed');
deepEqual(rejectNoOp, closed, 'reject is value no-op when closed');
assert(acceptNoOp !== closed && rejectNoOp !== closed, 'closed no-ops return fresh objects');

for (const malformed of [null, {}, { type: 'unknown' }, { type: 7 }, { type: 'open' }]) {
  throwsTypeError(
    () => transitionDecision(closed, malformed as unknown as DecisionAction),
    `rejects malformed action ${JSON.stringify(malformed)}`
  );
}

